Frontend UI (with localization).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Frontend UI (with localization) container

Container_Boundary(frontend_ui_with_localization, "Frontend UI (with localization)") {
    Component(Localization_Module, "Localization Module", "Flutter Localization Engine", "Manages dynamic localization and language packs for EU and US users.")
    Component(Offline_Storage_Module, "Offline Storage Module", "Local SQLite / Secure Storage", "Handles offline-first caching of patient session data and compliance records.")
    Component(UI_Presentation_Layer, "UI Presentation Layer", "Flutter Web/Mobile Widgets", "Renders responsive views for patients, clinicians, pharmacists, and auditors.")
}

Rel(Localization_Module, UI_Presentation_Layer, "Provides localized strings", "")
Rel(Offline_Storage_Module, UI_Presentation_Layer, "Syncs cached offline data", "")

@enduml

Video Streaming Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(video_streaming_service, "Video Streaming Service") {
    Component(Signaling___Session_Manager_Component, "Signaling & Session Manager Component", "Node.js/Go, gRPC/WebSockets", "Manages session signaling, connection negotiation, and real-time messaging for video consultations.")
    Component(Adaptive_Quality___Fallback_Controller_Component, "Adaptive Quality & Fallback Controller Component", "C++/WebRTC, DTLS/SCTP", "Controls video stream quality dynamically and manages fallback paths under unstable network conditions.")
    Component(TURN_Relay_Coordinator_Component, "TURN Relay Coordinator Component", "Coturn-based, UDP/TCP/TLS", "Coordinates NAT traversal and relay allocations for secure peer-to-peer media streams.")
}

Rel(Signaling___Session_Manager_Component, Adaptive_Quality___Fallback_Controller_Component, "Coordinates session state and adaptation parameters")
Rel(Signaling___Session_Manager_Component, TURN_Relay_Coordinator_Component, "Allocates relay paths for session media")
@enduml

AI Symptom Checker Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AI Symptom Checker Service container

Container_Boundary(ai_symptom_checker_service, "AI Symptom Checker Service") {
    Component(Triage_Controller, "Triage Controller", "FastAPI / Python", "Handles incoming symptom checking requests and orchestrates the triage workflow.")
    Component(AI_Inference_Engine, "AI Inference Engine", "PyTorch & GCP Vertex AI", "Powers regional AI symptom triage models with auto-scaling capabilities.")
    Component(Cryptographic_Signer, "Cryptographic Signer", "Google Cloud HSM", "Provides cryptographic hardware security for signing AI outputs ensuring EU MDR traceability.")
}

Rel(Triage_Controller, AI_Inference_Engine, "Sends symptom data for processing")
Rel(AI_Inference_Engine, Cryptographic_Signer, "Requests cryptographic signature for AI outputs")

@enduml

Immutable Logging Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(immutable_logging_service, "Immutable Logging Service") {
    Component(Log Ingestion Component, "Log Ingestion Component", "Go, gRPC/PubSub subscriber", "Ingests log entries via Pub/Sub and gRPC subscribers for immutable tracking.")
    Component(Cryptographic Verifier Component, "Cryptographic Verifier Component", "Go, Tink/Cloud HSM", "Verifies and signs logs cryptographically using Tink and Cloud HSM.")
    Component(WORM Storage Manager Component, "WORM Storage Manager Component", "Java/Go, GCP Cloud Storage Object Lock", "Manages Write Once, Read Many (WORM) storage using GCP Cloud Storage Object Lock.")
}

Rel(Log Ingestion Component, Cryptographic Verifier Component, "Sends ingested logs for cryptographic verification")
Rel(Cryptographic Verifier Component, WORM Storage Manager Component, "Forwards verified signed logs to WORM storage")
@enduml
